<template>
  <div class="enzyme-info-result">
    <section class="enzyme-identity" aria-label="Protein overview">
      <div class="identity-top"><a v-if="accession" :href="`https://www.uniprot.org/uniprotkb/${accession}/entry`" target="_blank" rel="noopener noreferrer" class="accession-link">{{ accession }} ↗</a><span v-if="data.reviewed != null" class="review-badge">{{ data.reviewed ? 'Reviewed · Swiss-Prot' : 'Unreviewed · TrEMBL' }}</span></div>
      <h4>{{ data.protein_name || (accession ? `Protein ${accession}` : 'Enzyme information') }}</h4>
      <p v-if="data.organism?.scientificName || data.gene_names?.length" class="identity-caption"><i>{{ data.organism?.scientificName }}</i><span v-if="data.organism?.commonName"> ({{ data.organism.commonName }})</span><span v-if="data.gene_names?.length"> · {{ data.gene_names.join(' / ') }}</span></p>
      <div class="identity-stats">
        <div v-if="sequence.length || data.sequence_info?.length"><strong>{{ (sequence.length || data.sequence_info.length).toLocaleString('en-US') }}<small> aa</small></strong><span>Sequence length</span></div>
        <div v-if="data.sequence_info?.mol_weight"><strong>{{ (data.sequence_info.mol_weight / 1000).toFixed(1) }}<small> kDa</small></strong><span>Molecular mass</span></div>
        <div v-if="sites.length"><strong>{{ sites.length }}</strong><span>Site annotations</span></div>
        <div v-if="pdbReferences.length"><strong>{{ pdbReferences.length }}</strong><span>PDB references</span></div>
      </div>
      <p v-if="data.function" class="protein-function">{{ data.function }}</p>
      <p v-else class="section-note">{{ data.partial ? 'Function description is unavailable in this snapshot.' : 'No function description was included in this result.' }}</p>
      <div v-if="data.cofactors?.length" class="cofactor-list"><span class="section-note">Cofactors</span><span v-for="cofactor in data.cofactors" :key="cofactor" class="cofactor">{{ cofactor }}</span></div>
    </section>

    <ReferenceStructure ref="reference" :accession="accession" :sequence="sequence" :sites="exactSites" :site-palette="annotationColors" @select="selectFromStructure" />

    <section class="enzyme-section" aria-label="Sequence and functional sites">
      <div class="section-heading"><div><span class="eyebrow">SEQUENCE &amp; SITES</span><h4>Read the sequence, locate the evidence</h4></div><button v-if="sequence" @click="exportFasta">Download FASTA</button></div>
      <template v-if="sequence">
        <div class="feature-map" aria-label="Annotated sites along the sequence">
          <div class="track-ruler"><span>1</span><span>{{ sequence.length }} aa</span></div>
          <div class="site-track"><button v-for="site in exactSites" :key="site.key" :style="{left:`${100 * (site.position-1) / Math.max(1,sequence.length-1)}%`,background:annotationColors[site.type] || '#6556c9'}" :title="`${site.type}: ${site.residue}${site.position} · ${site.label}`" :aria-label="`Select ${site.type} ${site.residue}${site.position}`" @click="selectPosition(site.position)"></button></div>
          <div v-if="regions.length" class="region-tracks"><div v-for="(region,i) in regions" :key="i" class="region-row"><span>{{ region.type }}</span><div><i :style="{left:`${(region.start-1)/sequence.length*100}%`,width:`${(region.end-region.start+1)/sequence.length*100}%`}" :title="`${region.description || region.type} · ${region.start}–${region.end}`"></i></div><small>{{ region.start }}–{{ region.end }}</small></div></div>
          <div class="annotation-legend"><span v-for="(color,name) in annotationColors" :key="name"><i :style="{background:color}"></i>{{ name }}</span><span>UniProt annotations</span></div>
        </div>
        <details open class="enzyme-details"><summary>Numbered amino acid sequence <span>{{ sequence.length }} residues</span></summary><SequencePreview :sequence="sequence" :annotations="sequenceMarks" :selected-position="selectedPosition" interactive @select="selectPosition" /></details>
        <p v-if="selectionNote" class="section-note" role="status">{{ selectionNote }}</p>
      </template>
      <p v-else class="empty-note">No sequence was included in this result. Available site annotations are listed below with their original numbering.</p>
      <details v-if="sites.length" open class="enzyme-details"><summary>Functional site annotations <span>{{ sites.length }} entries</span></summary>
        <ResultPreview title="UniProt functional site annotations"><div class="annotation-table"><table><thead><tr><th>Position</th><th>Annotation</th><th>Description / ligand</th></tr></thead><tbody><tr v-for="site in sites" :key="site.key" :class="{ 'selected-site':site.position === selectedPosition }"><td><button v-if="site.position" :aria-label="`Locate ${site.residue}${site.position}`" @click="selectPosition(site.position)">{{ site.residue }}{{ site.location }}</button><span v-else>{{ site.location }}</span></td><td><span class="site-label"><i :style="{background:annotationColors[site.type] || '#6556c9'}"></i>{{ site.type }}</span></td><td>{{ site.label }}<small v-if="site.ligand && site.ligand !== site.label">Ligand: {{ site.ligand }}</small><div v-if="site.evidences?.length" class="site-evidence"><span v-for="(evidence,i) in site.evidences" :key="i"><a v-if="evidence.source === 'PubMed' && /^\d+$/.test(evidence.id)" :href="`https://pubmed.ncbi.nlm.nih.gov/${evidence.id}/`" target="_blank" rel="noopener noreferrer">PMID {{ evidence.id }} ↗</a><span v-else>{{ evidence.evidenceCode || evidence.source }}</span></span></div></td></tr></tbody></table></div></ResultPreview>
      </details>
      <p v-else class="empty-note">No active-site or binding-site annotations were included. Missing annotations do not establish that these sites are absent.</p>
    </section>

    <section class="enzyme-section" aria-label="Catalytic reactions">
      <div class="section-heading"><div><span class="eyebrow">BIOCHEMISTRY</span><h4>Catalytic reactions</h4></div><span class="section-tag">Database annotations</span></div>
      <div v-for="(reaction,i) in data.catalytic_activities || []" :key="i" class="reaction-card"><div class="reaction-links"><a v-if="/^\d+\.(\d+|-)\.(\d+|-)\.(\d+|-)$/.test(reaction.ec_number)" :href="`https://enzyme.expasy.org/EC/${reaction.ec_number}`" target="_blank" rel="noopener noreferrer">EC {{ reaction.ec_number }} ↗</a><a v-if="/^\d+$/.test(reaction.rhea_id)" :href="`https://www.rhea-db.org/rhea/${reaction.rhea_id}`" target="_blank" rel="noopener noreferrer">Rhea {{ reaction.rhea_id }} ↗</a></div><p>{{ reaction.reaction || 'Reaction description was not included.' }}</p></div>
      <p v-if="!data.catalytic_activities?.length" class="empty-note">No catalytic reaction was included in this result. This alone does not establish whether the protein is an enzyme.</p>
      <details v-if="data.catalytic_activities?.some(r=>r.ec_number)" class="enzyme-details"><summary>Explore EC classification</summary><EcClassification :payload="data" /></details>
    </section>

    <section class="enzyme-section" aria-label="Reported kinetic parameters">
      <div class="section-heading"><div><span class="eyebrow">REPORTED MEASUREMENTS</span><h4>Kinetic parameters</h4></div><span v-if="kinetics.length" class="section-tag">Not platform predictions</span></div>
      <template v-if="kinetics.length"><p class="section-note">Measurements are grouped by reported unit. Assay conditions may differ; bar lengths alone do not establish relative catalytic efficiency.</p><div v-for="group in kinetics" :key="group.title"><ScientificChart v-if="group.rows.some(r=>r.value !== null)" :title="group.title" description="Reported UniProt values; consult the source for assay conditions." :rows="group.rows" x-label="Substrate / measurement" :y-label="`${group.name} (${group.unit})`" /><details class="enzyme-details"><summary>Original measurements · {{ group.title }}</summary><ScientificData :value="group.original" :column-order="['substrate','value','unit']" /></details></div></template>
      <p v-else class="empty-note">{{ data.partial || data.unavailable_sections?.includes('kinetic_parameters') ? 'Kinetic parameters are unavailable in this snapshot. They may exist in the full entry or literature.' : 'No numeric kinetic parameters were included in this result. This does not establish that no measurements have been reported.' }}</p>
      <p v-if="data.kinetic_parameters?.kcat_note" class="kinetic-note">{{ data.kinetic_parameters.kcat_note }}</p>
    </section>

    <details class="enzyme-details experimental-structures" :open="pdbReferences.length > 0"><summary>Experimental structure references <span>{{ pdbReferences.length ? `${pdbReferences.length} PDB entries` : 'Not included' }}</span></summary><div v-if="pdbReferences.length" class="pdb-grid"><a v-for="pdb in pdbReferences" :key="pdb.id" :href="`https://www.rcsb.org/structure/${pdb.id}`" target="_blank" rel="noopener noreferrer"><strong>{{ pdb.id }} ↗</strong><span>{{ pdb.method || 'Method not provided' }}</span><span v-if="pdb.resolution">{{ pdb.resolution }}</span><small v-if="pdb.chains">{{ pdb.chains }}</small></a></div><p v-else class="empty-note">No PDB references were included in this result. This does not imply that no experimental structure exists.</p><p v-if="pdbReferences.length" class="section-note">These are UniProt cross-references to experimental structures. Their chain coverage and numbering may differ from the AlphaFold model above.</p></details>
  </div>
</template>

<script setup>
import { computed, ref, watch } from 'vue';
import { downloadData } from '@/utils/workspace';
import { annotationColors, accessionId, annotationSites, kineticGroups } from '@/utils/enzymeInfo';
import ReferenceStructure from './ReferenceStructure.vue';
import SequencePreview from './SequencePreview.vue';
import ScientificChart from './ScientificChart.vue';
import ScientificData from './ScientificData.vue';
import ResultPreview from './ResultPreview.vue';
import EcClassification from './EcClassification.vue';

const props = defineProps({data:{type:Object,required:true}});
const sequence = computed(()=>typeof props.data.sequence_info?.sequence === 'string' ? props.data.sequence_info.sequence : '');
const accession = computed(()=>accessionId(props.data.uniprot_id));
const sites = computed(()=>annotationSites(props.data));
const exactSites = computed(()=>sites.value.filter(s=>s.position));
const sequenceMarks = computed(()=>exactSites.value.map(s=>({...s,color:annotationColors[s.type]})));
const regions = computed(()=>(props.data.sequence_features || []).filter(f=>Number.isInteger(f.start) && Number.isInteger(f.end) && f.start>0 && f.end>=f.start && f.end<=sequence.value.length));
const pdbReferences = computed(()=>(props.data.structure_references || []).filter(r=>/^[A-Za-z0-9]{4}$/.test(r.id)));
const kinetics = computed(()=>kineticGroups(props.data.kinetic_parameters));
const reference=ref(null),selectedPosition=ref(null),selectionNote=ref('');
function selectPosition(position){
  selectedPosition.value=position;
  if(reference.value?.focusPosition(position))selectionNote.value=`Selected ${sequence.value[position-1]}${position} in the sequence and reference structure.`;
  else selectionNote.value=`Selected ${sequence.value[position-1]}${position}. No validated matching coordinate is available for this residue. Load the reference structure to explore matching coordinates.`;
}
function selectFromStructure(position){selectedPosition.value=position;selectionNote.value=`Selected ${sequence.value[position-1]}${position} in the reference structure and sequence.`;}
watch(accession,()=>{selectedPosition.value=null;selectionNote.value='';});
function exportFasta(){downloadData(`>${accession.value || 'protein'} ${props.data.protein_name || ''}\n${sequence.value.match(/.{1,60}/g).join('\n')}\n`,`${accession.value || 'protein'}.fasta`,'text/plain');}
</script>

<style scoped>
