ection-heading h4{font-size:16px;line-height:1.5;margin:4px 0 0;font-weight:600}.section-note,.empty-note{font-size:12px;color:var(--color-text-secondary);line-height:1.75;margin:10px 0}.empty-note{padding:14px 16px;background:var(--color-background);border:1px dashed var(--color-border);border-radius:8px}.structure-meta{font-size:11px;color:var(--color-text-muted);gap:8px 16px;margin:14px 0}.enzyme-info-result a{color:var(--color-primary);text-decoration:none}.enzyme-info-result a:hover{text-decoration:underline}.enzyme-info-result button{cursor:pointer;background:var(--color-surface);border:1px solid var(--color-border);border-radius:5px;padding:6px 10px;font:inherit;font-size:11px;color:var(--color-primary)}.enzyme-info-result button:hover{background:var(--color-primary-light)}.structure-empty{display:flex;align-items:center;justify-content:center;gap:18px;padding:32px 20px;background:var(--color-background);border:1px solid var(--color-border);border-radius:12px;min-height:180px}.structure-placeholder-mark{width:56px;height:56px;flex-shrink:0;display:grid;place-items:center;border:1px solid var(--color-border);border-radius:14px;background:var(--color-primary-light);font-size:17px;color:var(--color-primary)}.structure-empty strong{font-size:13px}.structure-empty p{font-size:12px;line-height:1.7;max-width:460px;color:var(--color-text-secondary);margin:8px 0 12px}.inline-notice{font-size:12px;padding:12px 14px;border-left:3px solid #bf942a;background:#fffaf0;line-height:1.7}.enzyme-details{border:1px solid var(--color-border);border-radius:8px;padding:12px 14px;margin:12px 0;min-width:0}.enzyme-details>summary{cursor:pointer;font-size:12px;font-weight:550;line-height:1.6;color:var(--color-text-primary)}.enzyme-details>summary span{font-size:10px;font-weight:400;color:var(--color-text-muted);margin-left:8px}.enzyme-details[open]>summary{margin-bottom:16px}.enzyme-details :deep(.scientific-chart){border:0;padding:0;margin:12px 0}.feature-map{margin:18px 0 22px;padding:14px 16px;background:var(--color-background);border-radius:8px;border:1px solid var(--color-border)}.track-ruler{display:flex;justify-content:space-between;font:10px monospace;color:var(--color-text-muted)}.site-track{position:relative;height:6px;border-radius:3px;background:#dad5ee;margin:16px 7px 18px}.site-track button{position:absolute;top:50%;transform:translate(-50%,-50%);width:11px;height:20px;padding:0;border:2px solid white;border-radius:4px}.site-track button:focus-visible{outline:2px solid var(--color-primary);outline-offset:3px}.annotation-legend{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:10px;color:var(--color-text-secondary);margin-top:12px}.annotation-legend span,.site-label{display:inline-flex;align-items:center;gap:6px}.annotation-legend i,.site-label i{width:7px;height:7px;border-radius:50%;flex-shrink:0}.region-row{display:grid;grid-template-columns:85px 1fr 65px;align-items:center;gap:10px;font-size:10px;color:var(--color-text-muted);margin:8px 0}.region-row>div{height:6px;position:relative;background:#ebe8f3;border-radius:2px}.region-row i{height:6px;position:absolute;min-width:2px;background:#9386bc;border-radius:2px}.region-row small{text-align:right}.annotation-table{overflow:auto;max-height:400px}.annotation-table table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}.annotation-table th{font-size:10px;color:var(--color-text-muted);font-weight:500;background:var(--color-background)}.annotation-table th,.annotation-table td{padding:12px 10px;border-bottom:1px solid var(--color-border);vertical-align:top;line-height:1.65}.annotation-table td:first-child,.site-label{white-space:nowrap}.annotation-table td>small{display:block;color:var(--color-text-muted)}.annotation-table button{font-family:monospace;font-size:12px}.selected-site{background:var(--color-primary-light)}.site-evidence{font-size:10px;display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}.reaction-card{padding:16px;border:1px solid var(--color-border);bord