@container (max-width:500px){.enzyme-identity{padding:16px}.enzyme-identity h4{font-size:19px}.identity-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.section-heading h4{font-size:15px}.structure-empty{padding:22px 14px;gap:12px}.enzyme-details{padding:12px 10px}.region-row{grid-template-columns:68px 1fr 55px;gap:5px}.annotation-table th,.annotation-table td{padding:10px 7px}.section-heading{gap:10px}.enzyme-info-result :deep(.molecule-area){height:320px}}
